    for r in range(n):
        for c in range(len(grid[0])):
            if out[r][c] == 3:
                out[r][c] = 0

    # Motifs occupy square tiles separated by one blank row/column.
    if n == 19:
        size, stride = 4, 5
    elif n == 11:
        size, stride = 3, 4
    else:
        size = max(1, (n + 1) // 4)
        stride = size + 1

    nr = (n + stride - 1) // stride
    nc = (len(grid[0]) + stride - 1) // stride
    tiles = {}
    for tr in range(nr):
        for tc in range(nc):
            r0, c0 = tr * stride, tc * stride
            if r0 + size > n or c0 + size > len(grid[0]):
                continue
            motif = tuple(tuple(grid[r0+i][c0+j] for j in range(size))
                          for i in range(size))
            tiles[(tr, tc)] = motif

    def occupied(m):
        return any(v == 2 for row in m for v in row)

    # Complete 180-degree tile-position pairs where the counterpart is in
    # the 3-colored band.
    for (tr, tc), motif in list(tiles.items()):
        if not occupied(motif):
