        rr, cc = nr - 1 - tr, nc - 1 - tc
        if (rr, cc) not in tiles or occupied(tiles[(rr, cc)]):
            continue
        r0, c0 = rr * stride, cc * stride
        if any(grid[r0+i][c0+j] == 3 for i in range(size) for j in range(size)):
            tiles[(rr, cc)] = motif
            for i in range(size):
                for j in range(size):
                    out[r0+i][c0+j] = motif[i][j]

    counts = {}
    for m in tiles.values():
        if occupied(m):
            counts[m] = counts.get(m, 0) + 1

    # Mark one 2 in each repeated motif, toward the outward edge of its tile.
    for (tr, tc), motif in tiles.items():
        if not occupied(motif) or counts.get(motif, 0) < 2:
