def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The 3-colored strip occupies one full motif-sized tile.
    full_3_rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    full_3_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    size = len(full_3_rows) or len(full_3_cols)
    if size == 0:
        size = 3 if h == 11 else 4
    stride = size + 1

    # Remove the masking color.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0

    count = (h + 1) // stride
    tiles = {}
    patterns = {}
    for tr in range(count):
        for tc in range(count):
            r0, c0 = tr * stride, tc * stride
            if r0 + size > h or c0 + size > w:
                continue
            pat = tuple(tuple(2 if grid[r0+i][c0+j] == 2 else 0
                              for j in range(size))
                        for i in range(size))
            tiles[(tr, tc)] = pat
            if any(v == 2 for row in pat for v in row):
                patterns[pat] = patterns.get(pat, 0) + 1

    if not patterns:
        return out
    template = max(patterns, key=patterns.get)

    for (tr, tc), pat in tiles.items():
        r0, c0 = tr * stride, tc * stride
        masked = any(grid[r0+i][c0+j] == 3
                     for i in range(size) for j in range(size))

        if masked:
            # Restore only the motif pixels whose diagonal marker is present.
            if tr < size and tc < size and template[tr][tc] == 2:
                pat = template
                for i in range(size):
                    for j in range(size):
                        out[r0+i][c0+j] = pat[i][j]
        elif any(v == 2 for row in pat for v in row):
            # Mark the motif pixel indexed by this tile's position.
            if tr < size and tc < size and pat[tr][tc] == 2:
                out[r0+tr][c0+tc] = 8

        if masked and tr < size and tc < size and template[tr][tc] == 2:
            out[r0+tr][c0+tc] = 8

    return out
